"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { VisuallyHidden } from "./visually-hidden";

export type TrackerTone = "green" | "amber" | "red" | "accent" | "neutral";

export interface TrackerBlock {
  tone: TrackerTone;
  /** Tekst in de tooltip; zonder tekst blijft het blokje stil. */
  tooltip?: React.ReactNode;
  label?: string;
  color?: string;
}

export interface TrackerProps extends React.HTMLAttributes<HTMLDivElement> {
  data: TrackerBlock[];
  size?: "sm" | "md" | "lg";
  /** Tekst links en rechts onder de reeks, bv. "30 dagen geleden" en "vandaag". */
  startLabel?: React.ReactNode;
  endLabel?: React.ReactNode;
  /** Toegankelijke naam voor de hele reeks. */
  label?: string;
  emptyLabel?: React.ReactNode;
}

/**
 * Tracker — één blokje per periode, gekleurd naar status. De statuspagina-strook
 * voor uptime, builds of dagelijkse controles.
 */
export const Tracker = React.forwardRef<HTMLDivElement, TrackerProps>(function Tracker(
  { data, size = "md", startLabel, endLabel, label, emptyLabel = "Geen gegevens", className, ...rest },
  ref
) {
  const [actief, setActief] = React.useState<number | null>(null);

  if (data.length === 0) {
    return (
      <div ref={ref} className={cn("lui-tracker", className)} {...rest}>
        <div className="lui-chart-empty">{emptyLabel}</div>
      </div>
    );
  }

  return (
    <div ref={ref} className={cn("lui-tracker", `lui-tracker-${size}`, className)} {...rest}>
      <div className="lui-tracker-row" role="img" aria-label={label}>
        {data.map((blok, index) => (
          <span
            key={index}
            className="lui-tracker-block"
            data-tone={blok.tone}
            style={{ "--i": index, ...(blok.color ? { background: blok.color } : null) } as React.CSSProperties}
            onPointerEnter={() => setActief(index)}
            onPointerLeave={() => setActief((huidig) => (huidig === index ? null : huidig))}
          >
            {blok.label && <VisuallyHidden>{blok.label}</VisuallyHidden>}
            {actief === index && blok.tooltip !== undefined && (
              <span className="lui-tracker-tip" role="tooltip">
                {blok.tooltip}
              </span>
            )}
          </span>
        ))}
      </div>
      {(startLabel || endLabel) && (
        <div className="lui-tracker-foot">
          <span>{startLabel}</span>
          <span>{endLabel}</span>
        </div>
      )}
    </div>
  );
});

/* ============================ Tracker ============================ */
.lui-tracker { --lui-tracker-h: 28px; display: grid; gap: 7px; width: 100%; }
.lui-tracker-sm { --lui-tracker-h: 18px; }
.lui-tracker-lg { --lui-tracker-h: 40px; }

.lui-tracker-row { display: flex; gap: 2px; width: 100%; }
.lui-tracker-block {
  position: relative; flex: 1; min-width: 3px; height: var(--lui-tracker-h);
  border-radius: 3px; background: var(--surface-3);
  transition: opacity var(--dur-fast), transform var(--dur-fast);
}
.lui-tracker-block:hover { opacity: .8; transform: scaleY(1.08); }
.lui-tracker-block[data-tone="green"] { background: var(--green); }
.lui-tracker-block[data-tone="amber"] { background: var(--amber); }
.lui-tracker-block[data-tone="red"] { background: var(--red); }
.lui-tracker-block[data-tone="accent"] { background: var(--accent); }
.lui-tracker-block[data-tone="neutral"] { background: var(--surface-3); }

.lui-tracker-tip {
  position: absolute; bottom: calc(100% + 8px); left: 50%; transform: translateX(-50%);
  z-index: 2; padding: 5px 9px; white-space: nowrap;
  border: 1px solid var(--border); border-radius: var(--r-sm);
  background: var(--surface); box-shadow: var(--sh-lg);
  font-size: 12px; color: var(--text); pointer-events: none;
}

.lui-tracker-foot {
  display: flex; justify-content: space-between;
  font-size: var(--fs-xs); color: var(--text-3);
}

@media (prefers-reduced-motion: reduce) {
  .lui-tracker-block:hover { transform: none; }
}

/* ---------- Mount: blokjes rijzen op, van links naar rechts ---------- */
.lui-tracker-block {
  transform-origin: bottom;
  animation: lui-tracker-in .4s var(--ease-out) backwards;
  animation-delay: calc(var(--i, 0) * 12ms);
}
@keyframes lui-tracker-in { from { transform: scaleY(.2); opacity: 0; } }
